<?php namespace Inilim\Tool\Method\Arr;use Inilim\Tool\Arr;Arr :: __include('dataGet');function pluck(iterable $array,$value,$key=null):array{$results=[];$value=\is_string($value)?\explode('.',$value):$value;$key=$key===null||\is_array($key)?$key:\explode('.',$key);foreach($array as $item){$itemValue=\Inilim\Tool\Method\Arr\dataGet($item,$value);if($key===null){$results[]=$itemValue;}else{$itemKey=\Inilim\Tool\Method\Arr\dataGet($item,$key);if(\is_object($itemKey)&&\method_exists($itemKey,'__toString')){$itemKey=(string) $itemKey;}$results[$itemKey]=$itemValue;}}return $results;}